create table public.enterprise_service_requests (id uuid primary key default gen_random_uuid(),case_number text unique,enterprise_id uuid references public.enterprises(id) on delete set null,requester_user_id uuid references public.profiles(id) on delete set null,company_name text not null,contact_name text not null,contact_email text not null,contact_phone text,needs text[] not null default '{}',goal text,service_tier text not null default 'consult',status public.review_status not null default 'submitted',admin_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create sequence public.enterprise_case_seq start 1001; create or replace function public.set_enterprise_case_number() returns trigger language plpgsql set search_path=public as $$ begin if new.case_number is null then new.case_number := 'ESG-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.enterprise_case_seq')::text,5,'0'); end if; return new; end; $$; create trigger trg_enterprise_case_number before insert on public.enterprise_service_requests for each row execute function public.set_enterprise_case_number(); alter table public.enterprise_service_requests enable row level security; create policy "enterprise request owner read" on public.enterprise_service_requests for select to authenticated using (requester_user_id=(select auth.uid()) or (enterprise_id is not null and private.is_enterprise_user(enterprise_id)) or private.is_admin(null)); create policy "enterprise request signed in insert" on public.enterprise_service_requests for insert to authenticated with check (requester_user_id=(select auth.uid())); create policy "enterprise request admin update" on public.enterprise_service_requests for update to authenticated using (private.is_admin(null)) with check (private.is_admin(null)); create index idx_enterprise_service_requests_owner on public.enterprise_service_requests(requester_user_id,created_at desc); create index idx_enterprise_service_requests_status on public.enterprise_service_requests(status,created_at desc);
